#!/usr/bin/env node
/**
 * This run's explicitly authorized, preserve-data UI diagnostic wrapper only.
 * NOT a boot preflight, installer, HDC/VM manager or visual-acceptance oracle.
 * Before each operation, the caller must freshly establish the AGENTS.md boot,
 * SceneBoard and exact-target gates and pass preflightConfirmed:true. That flag
 * is an operator assertion, not evidence generated by this tool.
 *
 * node tools/reader-control-device-probe.mjs --target EXACT --hdc /absolute/hdc
 *   --server ::ffff:127.0.0.1:8710 --output-dir /absolute/evidence-directory
 * stdin JSON lines: {op:'click',x:100,y:200,preflightConfirmed:true}, etc.
 * Use JSON double quotes. quit/EOF releases only this process's shared target
 * lease. Set READER_HDC_LEASE_WAIT_MS to bound queueing (default 30000).
 * --self-test performs pure validation; it does not invoke HDC or touch locks.
 */
import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { createHash, randomUUID } from 'node:crypto';
import {
  accessSync, appendFileSync, constants, lstatSync, mkdirSync,
  readFileSync, realpathSync, statSync, writeFileSync,
} from 'node:fs';
import { isIP } from 'node:net';
import { basename, isAbsolute, parse, resolve } from 'node:path';
import { createInterface } from 'node:readline';
import { setTimeout as delay } from 'node:timers/promises';
import { acquireLease, canonicalServerKey, releaseLease, targetRef as serverRefHash } from './reader-hdc-lease.mjs';

const BUNDLE = 'io.reader.harmonyos';
const TIMEOUT_MS = 30000;
const MAX_OUTPUT = 4 * 1024 * 1024;
// Reviewed standalone diagnostic only; never accept an arbitrary executable
// merely because its caller knows a hash. Updating this pin needs code review.
const TOUCH_ELF_SHA256 = 'cc1b581bc6cf16449f5f535917fe68cc31cbb031cbc1a00caff8a4a87b02de00';
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const fatalOutput = /Connect server failed|Device not found|No devices|LIFECYCLE_TIMEOUT|SceneBoard exits 4times|kernel panic|guest reset|9568332|9568320|Error loading shared library|Error relocating|\berror\s*:|\bfailed\b/i;
const commandOK = result => !result.error && result.status === 0 &&
  !fatalOutput.test(`${result.stdout ?? ''}\n${result.stderr ?? ''}`);
const targetReference = target => createHash('sha256').update(target).digest('hex').slice(0, 12);
const fail = message => { throw new Error(message); };

function optionsFrom(argv) {
  const options = {};
  const keys = ['--target', '--hdc', '--server', '--output-dir'];
  for (let index = 0; index < argv.length; index += 2) {
    const key = argv[index];
    if (!keys.includes(key) || options[key] !== undefined || argv[index + 1] === undefined) fail('invalid/duplicate startup option');
    options[key] = argv[index + 1];
  }
  if (keys.some(key => typeof options[key] !== 'string' || options[key].length === 0)) fail('all four startup options are required');
  if (!/^[A-Za-z0-9._:\[\]-]{1,256}$/.test(options['--target']) || options['--target'].startsWith('-')) fail('invalid exact target');
  const server = options['--server'];
  const colon = server.lastIndexOf(':');
  const host = server.slice(0, colon).replace(/^\[|\]$/g, '');
  const port = server.slice(colon + 1);
  if (colon < 1 || (isIP(host) === 0 && host !== 'localhost') || !/^\d{1,5}$/.test(port) || Number(port) < 1 || Number(port) > 65535) fail('server must be an explicit IP/localhost and port');
  for (const key of ['--hdc', '--output-dir']) {
    if (!isAbsolute(options[key]) || /[\0\r\n]/.test(options[key])) fail(`${key} must be an absolute path`);
  }
  const outputDir = resolve(options['--output-dir']);
  if (outputDir === parse(outputDir).root) fail('output directory cannot be filesystem root');
  return { target: options['--target'], hdc: options['--hdc'], server, outputDir };
}

function exactFields(operation, names) {
  if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) fail('operation must be a JSON object');
  const allowed = ['op', 'preflightConfirmed', ...names];
  if (Object.keys(operation).some(key => !allowed.includes(key))) fail('unknown operation field');
}
function integer(value, min, max, name) {
  if (!Number.isInteger(value) || value < min || value > max) fail(`${name} must be an integer in ${min}..${max}`);
  return String(value);
}
function remotePath(path, extension) {
  if (typeof path !== 'string' || !/^\/data\/local\/tmp\/reader-control-[A-Za-z0-9][A-Za-z0-9._-]{0,120}\.(png|json)$/.test(path)) fail('device path must be a reader-control-* png/json file directly in /data/local/tmp');
  if (extension && !path.endsWith(extension)) fail(`operation requires ${extension}`);
  return path;
}
function dragArguments(operation) {
  return [integer(operation.fromX, 0, 16384, 'fromX'), integer(operation.fromY, 0, 16384, 'fromY'),
    integer(operation.toX, 0, 16384, 'toX'), integer(operation.toY, 0, 16384, 'toY'),
    integer(operation.velocity ?? 600, 200, 40000, 'velocity')];
}
function sampleDelays(values) {
  if (!Array.isArray(values) || values.length < 1 || values.length > 5) fail('sampling requires 1..5 delays');
  values.forEach(value => integer(value, 0, 10000, 'sample delay'));
  if (values.some((value, index) => index > 0 && value <= values[index - 1])) fail('sample delays must be strictly increasing');
  return values.slice();
}
function touchPlanText(events, width, height) {
  if (!Array.isArray(events) || events.length < 2 || events.length > 256) fail('touch plan requires 2..256 events');
  const active = new Set();
  let previousTime = -1;
  let cancelTime;
  const lines = events.map(event => {
    if (!event || typeof event !== 'object' || Array.isArray(event) ||
      Object.keys(event).length !== 5 || Object.keys(event).some(key => !['atMs', 'action', 'finger', 'x', 'y'].includes(key))) fail('touch event requires exactly atMs/action/finger/x/y');
    integer(event.atMs, 0, 10000, 'event time');
    integer(event.finger, 0, 1, 'finger');
    integer(event.x, 0, width - 1, 'touch x');
    integer(event.y, 0, height - 1, 'touch y');
    if (!['DOWN', 'MOVE', 'UP', 'CANCEL'].includes(event.action)) fail('invalid touch action');
    if (event.atMs < previousTime) fail('touch event time moved backwards');
    if (cancelTime !== undefined && (event.action !== 'CANCEL' || event.atMs !== cancelTime)) fail('CANCEL must be a final simultaneous release group');
    if (event.action === 'DOWN') {
      if (active.has(event.finger)) fail('duplicate DOWN');
      active.add(event.finger);
    } else {
      if (!active.has(event.finger)) fail('touch event has no owning DOWN');
      if (event.action === 'UP' || event.action === 'CANCEL') active.delete(event.finger);
      if (event.action === 'CANCEL') cancelTime = event.atMs;
    }
    previousTime = event.atMs;
    return `${event.atMs} ${event.action} ${event.finger} ${event.x} ${event.y}`;
  });
  if (active.size) fail('touch plan must release all pointers');
  return `${lines.join('\n')}\n`;
}
function operationPlan(operation, outputDir) {
  exactFields(operation, ['x', 'y', 'fromX', 'fromY', 'toX', 'toY', 'velocity', 'key', 'path', 'text', 'explicitPermit', 'sampleDelaysMs',
    'elfPath', 'elfSha256', 'width', 'height', 'display', 'plan', 'ticket', 'requestAuth', 'durationMs']);
  if (operation.op === 'quit') {
    exactFields(operation, []);
    return { kind: 'quit' };
  }
  if (operation.preflightConfirmed !== true) fail('fresh external boot/SceneBoard/exact-target preflight confirmation is required');
  const shell = (...args) => ({ kind: 'command', args: ['shell', ...args] });
  if (operation.op === 'prepareTouchSequence') {
    exactFields(operation, ['elfPath', 'elfSha256', 'width', 'height', 'display', 'plan']);
    if (typeof operation.elfPath !== 'string' || !isAbsolute(operation.elfPath) || /[\0\r\n]/.test(operation.elfPath) ||
      basename(operation.elfPath) !== 'reader-control-touch-sequence') fail('only an absolute reader-control-touch-sequence ELF path is accepted');
    if (operation.elfSha256 !== TOUCH_ELF_SHA256) fail('ELF SHA is not the reviewed diagnostic pin');
    integer(operation.width, 1, 16384, 'width'); integer(operation.height, 1, 16384, 'height');
    integer(operation.display, 0, 15, 'display');
    return { kind: 'prepareTouchSequence', elfPath: operation.elfPath, elfSha256: operation.elfSha256,
      width: operation.width, height: operation.height, display: operation.display,
      planText: touchPlanText(operation.plan, operation.width, operation.height) };
  }
  if (['dryRunTouchSequence', 'sampledTouchSequence'].includes(operation.op)) {
    const execute = operation.op === 'sampledTouchSequence';
    exactFields(operation, ['ticket', ...(execute ? ['requestAuth', 'sampleDelaysMs'] : [])]);
    if (typeof operation.ticket !== 'string' || !uuidPattern.test(operation.ticket)) fail('invalid touch ticket');
    if (execute && operation.requestAuth !== true) fail('each execution requires requestAuth:true for this reviewed plan');
    return { kind: operation.op, ticket: operation.ticket,
      ...(execute ? { sampleDelaysMs: sampleDelays(operation.sampleDelaysMs) } : {}) };
  }
  if (operation.op === 'click' || operation.op === 'longClick') {
    exactFields(operation, ['x', 'y']);
    return shell('uitest', 'uiInput', operation.op, integer(operation.x, 0, 16384, 'x'), integer(operation.y, 0, 16384, 'y'));
  }
  if (operation.op === 'sampledClick') {
    exactFields(operation, ['x', 'y', 'sampleDelaysMs']);
    return { kind: 'sampledClick', args: ['shell', 'uitest', 'uiInput', 'click',
      integer(operation.x, 0, 16384, 'x'), integer(operation.y, 0, 16384, 'y')],
      sampleDelaysMs: sampleDelays(operation.sampleDelaysMs) };
  }
  if (operation.op === 'heldTouch') {
    exactFields(operation, ['x', 'y', 'durationMs', 'sampleDelaysMs']);
    const x = integer(operation.x, 0, 16384, 'x');
    const y = integer(operation.y, 0, 16384, 'y');
    const duration = integer(operation.durationMs, 1, 3000, 'durationMs');
    // Reviewed official uinput grammar: one process, same-coordinate DOWN,
    // interval, UP. Never expose bare MOVE, arbitrary argv, CANCEL or finger ID.
    const args = ['shell', 'uinput', '-T', '-d', x, y, '-i', duration, '-u', x, y];
    return operation.sampleDelaysMs === undefined ? { kind: 'command', args } :
      { kind: 'sampledHeldTouch', args, sampleDelaysMs: sampleDelays(operation.sampleDelaysMs) };
  }
  if (operation.op === 'inputText') {
    exactFields(operation, ['x', 'y', 'text']);
    // Verified from this target's uiInput help. A search-only word allowlist
    // excludes every shell metacharacter, option prefix and argument separator;
    // HDC shell must never receive unrestricted interpolated text.
    if (typeof operation.text !== 'string' || !/^[\p{L}\p{N}]{1,64}$/u.test(operation.text)) {
      fail('inputText accepts only a 1..64 character letter/number search word');
    }
    return shell('uitest', 'uiInput', 'inputText', integer(operation.x, 0, 16384, 'x'),
      integer(operation.y, 0, 16384, 'y'), operation.text);
  }
  if (['drag', 'swipe', 'sampledDrag'].includes(operation.op)) {
    exactFields(operation, ['fromX', 'fromY', 'toX', 'toY', 'velocity', ...(operation.op === 'sampledDrag' ? ['sampleDelaysMs'] : [])]);
    const args = ['shell', 'uitest', 'uiInput', operation.op === 'swipe' ? 'swipe' : 'drag', ...dragArguments(operation)];
    if (operation.op !== 'sampledDrag') return { kind: 'command', args };
    if (!Array.isArray(operation.sampleDelaysMs) || operation.sampleDelaysMs.length < 1 || operation.sampleDelaysMs.length > 5) fail('sampledDrag requires 1..5 sampleDelaysMs');
    operation.sampleDelaysMs.forEach(value => integer(value, 0, 10000, 'sample delay'));
    if (operation.sampleDelaysMs.some((value, index) => index > 0 && value <= operation.sampleDelaysMs[index - 1])) fail('sample delays must be strictly increasing');
    return { kind: 'sampledDrag', args, sampleDelaysMs: operation.sampleDelaysMs.slice() };
  }
  if (operation.op === 'keyEvent') {
    exactFields(operation, ['key']);
    if (!['Back', 'Home'].includes(operation.key)) fail('only Back/Home key events are allowed');
    return shell('uitest', 'uiInput', 'keyEvent', operation.key);
  }
  if (operation.op === 'dumpLayout' || operation.op === 'screenCap') {
    exactFields(operation, ['path']);
    return shell('uitest', operation.op, '-p', remotePath(operation.path, operation.op === 'screenCap' ? '.png' : '.json'));
  }
  if (operation.op === 'recv') {
    exactFields(operation, ['path']);
    const path = remotePath(operation.path);
    return { kind: 'command', args: ['file', 'recv', path, resolve(outputDir, basename(path))], localPath: resolve(outputDir, basename(path)) };
  }
  if (operation.op === 'start') {
    exactFields(operation, []);
    return shell('aa', 'start', '-a', 'EntryAbility', '-b', BUNDLE, '-m', 'entry', '--pb', 'readerControlMotionVerification', 'true');
  }
  if (operation.op === 'startNormal') {
    exactFields(operation, []);
    return shell('aa', 'start', '-a', 'EntryAbility', '-b', BUNDLE, '-m', 'entry');
  }
  if (operation.op === 'listGeometryLog') {
    exactFields(operation, []);
    return shell('hilog', '-x', '-e', 'ReaderControlListProbe');
  }
  if (operation.op === 'motionLog') {
    exactFields(operation, []);
    return shell('hilog', '-x', '-e', 'ReaderControlMotionProbe');
  }
  if (operation.op === 'force-stop') {
    exactFields(operation, ['explicitPermit']);
    if (operation.explicitPermit !== true) fail('force-stop requires explicitPermit:true for the current operation');
    return shell('aa', 'force-stop', BUNDLE);
  }
  fail('operation is not on the diagnostic whitelist');
}

// Retained for the pure self-test's ownership predicate; production target
// locking is delegated to the shared cross-process HDC lease.
function ownerMatches(owner, expected) {
  return owner?.pid === expected.pid && owner?.targetRef === expected.targetRef && owner?.probeNonce === expected.probeNonce;
}

function evidenceEntryExists(path) {
  try { lstatSync(path); return true; }
  catch (error) { if (error.code === 'ENOENT') return false; throw error; }
}
function pngExtent(bytes) {
  if (!bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) fail('capture is not PNG');
  let offset = 8;
  let chunks = 0;
  while (offset + 12 <= bytes.length) {
    const length = bytes.readUInt32BE(offset);
    const type = bytes.toString('ascii', offset + 4, offset + 8);
    const next = offset + length + 12;
    if (next > bytes.length) fail('truncated PNG chunk');
    chunks += 1;
    if (type === 'IEND') {
      if (length !== 0 || next !== bytes.length) fail('PNG has invalid end or trailing bytes; evidence rejected');
      return { bytes: bytes.length, chunks };
    }
    offset = next;
  }
  fail('PNG has no complete IEND');
}
async function acquireTargetLock(target, hdc, configuredServer) {
  const targetRef = targetReference(target);
  // HDC session/channel state is shared by all targets on one server.
  const serverKey = canonicalServerKey(configuredServer || process.env.READER_HDC_SERVER_KEY || '127.0.0.1:8710');
  const serverRef = serverRefHash(serverKey);
  const root = process.env.READER_HDC_LEASE_ROOT || '/private/tmp/reader-hdc-target-leases';
  const owner = {
    pid: process.pid, ppid: process.ppid, agentId: process.env.CODEX_AGENT_ID || process.env.AGENT_ID || 'unspecified',
    target, targetRef, serverKey, serverRef, hdc, command: ['probe-session'], startedAt: new Date().toISOString(), token: randomUUID(),
  };
  const configuredWait = Number(process.env.READER_HDC_LEASE_WAIT_MS || '30000');
  const waitMs = Number.isInteger(configuredWait) && configuredWait >= 0 && configuredWait <= 3600000 ? configuredWait : 30000;
  const lease = await acquireLease({ root, target, targetRefValue: targetRef, lockRefValue: serverRef, waitMs, owner });
  return {
    targetRef,
    release() { releaseLease(root, lease.lockDir, owner); },
  };
}

async function probe(options) {
  accessSync(options.hdc, constants.X_OK);
  if (!statSync(options.hdc).isFile()) fail('hdc must be an executable file');
  const lock = await acquireTargetLock(options.target, options.hdc, options.server);
  let input;
  let activeChild;
  let stopping = false;
  let frameIndex = 0;
  // A reused remote name cannot establish capture provenance across runs.
  // Give every probe a unique namespace; never overwrite earlier evidence.
  const frameRunNonce = randomUUID();
  const abort = new AbortController();
  const stop = () => { stopping = true; abort.abort(); activeChild?.kill('SIGTERM'); input?.close(); };
  process.on('SIGINT', stop);
  process.on('SIGTERM', stop);
  process.on('SIGHUP', stop);
  try {
    mkdirSync(options.outputDir, { recursive: true, mode: 0o700 });
    options.outputDir = realpathSync(options.outputDir);
    const log = resolve(options.outputDir, `reader-control-probe-${Date.now()}-${randomUUID()}.jsonl`);
    writeFileSync(log, '', { flag: 'wx', mode: 0o600 });
    const redact = value => String(value ?? '').split(options.target).join(`[target:${lock.targetRef}]`);
    const record = value => {
      const line = `${JSON.stringify({ recordedAt: new Date().toISOString(), targetRef: lock.targetRef, ...value })}\n`;
      appendFileSync(log, line);
      process.stdout.write(line);
    };
    const prefix = ['-p', '-s', options.server, '-t', options.target];
    const assess = (args, result, startedAt, elapsedMs) => {
      const stdout = redact(result.stdout);
      const stderr = redact(result.stderr);
      const ok = commandOK(result);
      record({ event: 'command', args, startedAt, elapsedMs, ok, status: result.status,
        signal: result.signal ?? null, error: result.error ? redact(result.error.message) : null, stdout, stderr });
      if (!ok) fail('device command failed or stop-condition output observed; no automatic retry');
    };
    const run = plan => {
      if (stopping) fail('probe is stopping');
      if (plan.localPath && evidenceEntryExists(plan.localPath)) fail('refusing to overwrite existing local evidence or symlink');
      const start = performance.now();
      const startedAt = new Date().toISOString();
      const result = spawnSync(options.hdc, [...prefix, ...plan.args], {
        shell: false, encoding: 'utf8', timeout: TIMEOUT_MS, maxBuffer: MAX_OUTPUT, stdio: ['ignore', 'pipe', 'pipe'],
      });
      assess(plan.args, result, startedAt, performance.now() - start);
      if (plan.localPath) {
        if (plan.artifactSha256 && (!lstatSync(plan.localPath).isFile() || lstatSync(plan.localPath).isSymbolicLink())) fail('touch artifact readback is not a regular file');
        const bytes = readFileSync(plan.localPath);
        const actualSha256 = sha256(bytes);
        if (plan.artifactSha256 && actualSha256 !== plan.artifactSha256) {
          record({ event: 'touch-artifact-mismatch', path: plan.localPath, expectedSha256: plan.artifactSha256, actualSha256 });
          fail('remote touch artifact SHA mismatch; no execution');
        }
        const extent = plan.artifactSha256 ? { bytes: bytes.length, artifactShaVerified: true } : plan.localPath.endsWith('.png') ? pngExtent(bytes) :
          { bytes: bytes.length, jsonParsed: Boolean(JSON.parse(bytes.toString('utf8'))) };
        record({ event: 'capture-integrity', path: plan.localPath,
          sha256: actualSha256, ...extent,
          meaning: 'file extent/parse and identity only; not visual or interaction acceptance' });
      }
      return result;
    };
    const touchTickets = new Map();
    const verifyTouchArtifacts = ticket => {
      for (const artifact of ticket.artifacts) {
        // Every verification gets a new local name: no stale content, symlink
        // or previous successful readback can substitute for this operation.
        const localPath = resolve(options.outputDir, `reader-control-${ticket.id}-${randomUUID()}-${artifact.name}.readback`);
        run({ args: ['file', 'recv', artifact.remotePath, localPath], localPath, artifactSha256: artifact.sha256 });
      }
    };
    const prepareTouchSequence = plan => {
      const info = lstatSync(plan.elfPath);
      if (!info.isFile() || info.isSymbolicLink() || info.size < 64 || info.size > MAX_OUTPUT) fail('ELF must be a regular bounded file, not a symlink');
      const bytes = readFileSync(plan.elfPath);
      if (sha256(bytes) !== plan.elfSha256 || bytes.toString('hex', 0, 4) !== '7f454c46' ||
        bytes[4] !== 2 || bytes[5] !== 1 || bytes.readUInt16LE(18) !== 183) fail('ELF identity/architecture does not match reviewed aarch64 diagnostic');
      const id = randomUUID();
      const remoteDir = `/data/local/tmp/reader-control-input-${id}`;
      const ticket = { id, width: plan.width, height: plan.height, display: plan.display,
        steps: plan.planText.trimEnd().split('\n').length, remoteDir, dryRunPassed: false,
        artifacts: [{ name: 'reader-control-touch-sequence', bytes, sha256: plan.elfSha256 },
          { name: 'reviewed.plan', bytes: Buffer.from(plan.planText), sha256: sha256(plan.planText) }] };
      for (const artifact of ticket.artifacts) {
        artifact.localPath = resolve(options.outputDir, `reader-control-${id}-${artifact.name}`);
        artifact.remotePath = `${remoteDir}/${artifact.name}`;
        // Stage the already-verified bytes, never transfer a mutable caller
        // file and then mistake its earlier checksum for transferred identity.
        writeFileSync(artifact.localPath, artifact.bytes, { flag: 'wx', mode: 0o600 });
        delete artifact.bytes;
      }
      record({ event: 'touch-prepare', ticket: id, remoteDir, width: ticket.width, height: ticket.height,
        display: ticket.display, planText: plan.planText, artifacts: ticket.artifacts,
        meaning: 'preparation only; exclusive remote mkdir, no permission request or input' });
      // No -p, delete, overwrite or reuse. Failure is terminal; partial files
      // remain for inspection, never cleaned outside this owned namespace.
      run({ args: ['shell', 'mkdir', remoteDir] });
      record({ event: 'touch-owned-directory-created', ticket: id, remoteDir });
      for (const artifact of ticket.artifacts) {
        run({ args: ['file', 'send', artifact.localPath, artifact.remotePath] });
      }
      verifyTouchArtifacts(ticket);
      run({ args: ['shell', 'chmod', '700', ticket.artifacts[0].remotePath] });
      touchTickets.set(id, ticket);
      record({ event: 'touch-prepared', ticket: id, remoteDir, artifacts: ticket.artifacts,
        meaning: 'both remote byte identities verified; dry-run still required; no input executed' });
    };
    const touchInvocation = (ticket, execute) => {
      // Every string is tool-generated from a UUID namespace or a validated
      // integer. The sole shell operator is fixed stdin redirection; callers
      // cannot pass a command, argument, path, plan token or redirection.
      return ['shell', ticket.artifacts[0].remotePath, execute ? '--execute' : '--dry-run',
        String(ticket.width), String(ticket.height), '--display', String(ticket.display),
        ...(execute ? ['--request-authorization'] : []), '<', ticket.artifacts[1].remotePath];
    };
    const resolveTouchTicket = plan => {
      const ticket = touchTickets.get(plan.ticket);
      if (!ticket) fail('touch ticket is not owned by this live exact-target probe');
      verifyTouchArtifacts(ticket);
      return ticket;
    };
    const dryRunTouchSequence = plan => {
      const ticket = resolveTouchTicket(plan);
      const result = run({ args: touchInvocation(ticket, false) });
      const events = String(result.stdout).split(/\r?\n/).filter(line => line.startsWith('{')).map(line => JSON.parse(line));
      const validated = events.find(event => event.event === 'validated-plan');
      if (!validated || validated.dryRun !== true || validated.steps !== ticket.steps ||
        validated.width !== ticket.width || validated.height !== ticket.height || validated.display !== ticket.display ||
        events.some(event => ['touch', 'request-authorization', 'authorization'].includes(event.event))) fail('native dry-run did not confirm the bound plan without input');
      ticket.dryRunPassed = true;
      record({ event: 'touch-dry-run-passed', ticket: ticket.id, validated,
        meaning: 'native parser only; no authorization or injected touch' });
    };
    const sampledTouchSequence = async plan => {
      const ticket = resolveTouchTicket(plan);
      if (!ticket.dryRunPassed) fail('this ticket requires a successful native dry-run before execution');
      const args = touchInvocation(ticket, true);
      const startedAt = new Date().toISOString();
      const commandStart = performance.now();
      let stdout = '', stderr = '', pendingLine = '', childError, origin;
      let originReady;
      const started = new Promise(resolveStarted => { originReady = resolveStarted; });
      record({ event: 'touch-execute-admitted', ticket: ticket.id, requestAuth: true, artifacts: ticket.artifacts,
        meaning: 'fresh caller preflight asserted; helper must obtain its own new authorization, never reuse another owner' });
      activeChild = spawn(options.hdc, [...prefix, ...args], { shell: false,
        stdio: ['ignore', 'pipe', 'pipe'], timeout: TIMEOUT_MS });
      const child = activeChild;
      const nativeEvents = [];
      const completed = new Promise(resolveDone => {
        const bad = message => { childError = new Error(message); stop(); };
        const inspect = () => {
          if (stdout.length > MAX_OUTPUT || stderr.length > MAX_OUTPUT || fatalOutput.test(`${stdout}\n${stderr}`)) bad('touch helper output limit or stop condition');
        };
        child.stdout.on('data', bytes => {
          stdout += bytes; pendingLine += bytes; inspect();
          let newline;
          while ((newline = pendingLine.indexOf('\n')) >= 0) {
            const line = pendingLine.slice(0, newline).trim(); pendingLine = pendingLine.slice(newline + 1);
            if (!line.startsWith('{')) continue; // Preserve HDC transport text in raw command receipt.
            let event;
            try { event = JSON.parse(line); } catch { bad('invalid helper JSONL'); break; }
            nativeEvents.push(event);
            record({ event: 'touch-helper-event', ticket: ticket.id, receivedAfterCommandMs: performance.now() - commandStart, native: event });
            if (event.event === 'touch' && event.index === 0 && event.action === 'DOWN' && event.code === 0 && !origin) {
              origin = { hostMonotonicMs: performance.now(), receivedAt: new Date().toISOString(),
                scheduledMs: event.scheduledMs, nativeActualMs: event.actualMs };
              record({ event: 'touch-sampling-origin', ticket: ticket.id, ...origin,
                meaning: 'host receipt of first successful DOWN API call; excludes authorization wait, not app/render frame time' });
              originReady(origin);
            }
          }
        });
        child.stderr.on('data', bytes => { stderr += bytes; inspect(); });
        child.on('error', error => { childError = error; });
        child.on('close', (status, signal) => {
          const result = { status, signal, stdout, stderr, error: childError };
          if (!commandOK(result)) stop();
          originReady(undefined);
          resolveDone(result);
        });
      });
      try {
        const reference = await started;
        if (!reference) {
          assess(args, await completed, startedAt, performance.now() - commandStart);
          fail('helper exited without successful DOWN; no gesture screenshots triggered');
        }
        for (const requestedDelayMs of plan.sampleDelaysMs) {
          await delay(Math.max(0, requestedDelayMs - (performance.now() - reference.hostMonotonicMs)), undefined, { signal: abort.signal });
          if (stopping) fail('probe is stopping');
          const path = `/data/local/tmp/reader-control-${frameRunNonce}-frame-${frameIndex++}.png`;
          record({ event: 'sample-trigger', ticket: ticket.id, requestedDelayMs,
            triggerAfterMs: performance.now() - reference.hostMonotonicMs, path,
            timingMeaning: 'screenCap command trigger relative to host receipt of successful DOWN, not precise native/render timestamp' });
          run(operationPlan({ op: 'screenCap', path, preflightConfirmed: true }, options.outputDir));
          await delay(0, undefined, { signal: abort.signal });
          run(operationPlan({ op: 'recv', path, preflightConfirmed: true }, options.outputDir));
        }
        assess(args, await completed, startedAt, performance.now() - commandStart);
        const complete = nativeEvents.find(event => event.event === 'complete');
        const revoked = nativeEvents.find(event => event.event === 'authorization' && event.phase === 'after-revoke');
        if (!complete || complete.result !== 0 || !revoked || revoked.code !== 0 || revoked.status !== 0) fail('helper lacks successful completion/revoked authorization receipt');
        record({ event: 'touch-execute-completed', ticket: ticket.id,
          meaning: 'helper API completion and own authorization revoked; app event delivery and visual acceptance require independent evidence' });
      } catch (error) {
        child.kill('SIGTERM');
        const result = await completed;
        if (!commandOK(result)) assess(args, result, startedAt, performance.now() - commandStart);
        throw error;
      } finally { activeChild = undefined; }
    };
    // Shared bounded transport sampler for reviewed drag/click/heldTouch argv.
    // Origin is command dispatch, not confirmed native DOWN or rendered time.
    const sampledDrag = async plan => {
      const start = performance.now();
      const startedAt = new Date().toISOString();
      let stdout = '';
      let stderr = '';
      let childError;
      activeChild = spawn(options.hdc, [...prefix, ...plan.args], {
        shell: false, stdio: ['ignore', 'pipe', 'pipe'], timeout: TIMEOUT_MS,
      });
      const child = activeChild;
      const completed = new Promise(resolveDone => {
        const inspectOutput = () => {
          if (stdout.length > MAX_OUTPUT || stderr.length > MAX_OUTPUT || fatalOutput.test(`${stdout}\n${stderr}`)) {
            childError = new Error('drag output limit or stop condition');
            stop(); // Do not issue another screenshot after a failed drag.
          }
        };
        child.stdout.on('data', bytes => { stdout += bytes; inspectOutput(); });
        child.stderr.on('data', bytes => { stderr += bytes; inspectOutput(); });
        child.on('error', error => { childError = error; });
        child.on('close', (status, signal) => {
          const dragResult = { status, signal, stdout, stderr, error: childError };
          if (!commandOK(dragResult)) stop();
          resolveDone(dragResult);
        });
      });
      try {
        for (const requestedDelayMs of plan.sampleDelaysMs) {
          await delay(Math.max(0, requestedDelayMs - (performance.now() - start)), undefined, { signal: abort.signal });
          if (stopping) fail('probe is stopping');
          const path = `/data/local/tmp/reader-control-${frameRunNonce}-frame-${frameIndex++}.png`;
          const receive = operationPlan({ op: 'recv', path, preflightConfirmed: true }, options.outputDir);
          if (evidenceEntryExists(receive.localPath)) fail('refusing to overwrite existing sampled evidence');
          record({ event: 'sample-trigger', requestedDelayMs, triggerAfterMs: performance.now() - start, path,
            timingMeaning: 'actual screenshot command trigger, not an exact rendered-frame timestamp' });
          run(operationPlan({ op: 'screenCap', path, preflightConfirmed: true }, options.outputDir));
          // Drain asynchronous drag errors before admitting another command.
          await delay(0, undefined, { signal: abort.signal });
          run(receive);
        }
        assess(plan.args, await completed, startedAt, performance.now() - start);
      } catch (error) {
        child.kill('SIGTERM');
        const result = await completed;
        // Preserve the failing drag's output even when it aborts a pending
        // screenshot delay, rather than reporting only a timer AbortError.
        if (!commandOK(result)) assess(plan.args, result, startedAt, performance.now() - start);
        throw error;
      } finally { activeChild = undefined; }
    };
    record({ event: 'ready', log, warning: 'Lock acquired only; boot readiness/authorization must already be established externally. No retries or service startup.' });
    input = createInterface({ input: process.stdin, crlfDelay: Infinity });
    for await (const line of input) {
      if (stopping) break;
      if (line.length > 32768) fail('operation line exceeds limit');
      if (line.trim() === '') continue;
      const plan = operationPlan(JSON.parse(line), options.outputDir);
      if (plan.kind === 'quit') break;
      if (['sampledDrag', 'sampledClick', 'sampledHeldTouch'].includes(plan.kind)) await sampledDrag(plan);
      else if (plan.kind === 'prepareTouchSequence') prepareTouchSequence(plan);
      else if (plan.kind === 'dryRunTouchSequence') dryRunTouchSequence(plan);
      else if (plan.kind === 'sampledTouchSequence') await sampledTouchSequence(plan);
      else run(plan);
    }
    record({ event: 'closed', reason: stopping ? 'signal' : 'quit-or-eof' });
  } finally {
    input?.close();
    process.off('SIGINT', stop);
    process.off('SIGTERM', stop);
    process.off('SIGHUP', stop);
    lock.release();
  }
}

function selfTest() {
  const png = Buffer.from('89504e470d0a1a0a0000000049454e44ae426082', 'hex');
  assert.equal(pngExtent(png).bytes, png.length);
  assert.throws(() => pngExtent(Buffer.concat([png, Buffer.from('stale tail')])));
  assert.throws(() => pngExtent(png.subarray(0, png.length - 1)));
  const directory = '/private/tmp/probe-self-test-evidence';
  const plan = value => operationPlan({ preflightConfirmed: true, ...value }, directory);
  const validArgs = ['--target', 'test-serial', '--hdc', '/absolute/hdc', '--server', '::ffff:127.0.0.1:8710', '--output-dir', directory];
  assert.equal(optionsFrom(validArgs).server, '::ffff:127.0.0.1:8710');
  assert.throws(() => optionsFrom([...validArgs, '--target', 'other']));
  assert.throws(() => optionsFrom(validArgs.map(value => value === 'test-serial' ? 'x; reboot' : value)));
  assert.throws(() => operationPlan({ op: 'click', x: 1, y: 2 }, directory));
  assert.deepEqual(plan({ op: 'click', x: 1, y: 2 }).args, ['shell', 'uitest', 'uiInput', 'click', '1', '2']);
  for (const op of ['click', 'longClick']) assert.throws(() => plan({ op, x: '1; reboot', y: 2 }));
  assert.deepEqual(plan({ op: 'inputText', x: 1, y: 2, text: '正文Reader123' }).args,
    ['shell', 'uitest', 'uiInput', 'inputText', '1', '2', '正文Reader123']);
  for (const text of ['', 'x;reboot', 'a b', 'a\nb', '-h', '$(id)', '`id`', "'x'", '字'.repeat(65)]) {
    assert.throws(() => plan({ op: 'inputText', x: 1, y: 2, text }));
  }
  for (const op of ['drag', 'swipe']) {
    assert.equal(plan({ op, fromX: 1, fromY: 2, toX: 3, toY: 4 }).args.at(-1), '600');
    assert.throws(() => plan({ op, fromX: 1, fromY: 2, toX: 3, toY: 4, velocity: 199 }));
  }
  assert.deepEqual(plan({ op: 'keyEvent', key: 'Back' }).args, ['shell', 'uitest', 'uiInput', 'keyEvent', 'Back']);
  assert.deepEqual(plan({ op: 'motionLog' }).args, ['shell', 'hilog', '-x', '-e', 'ReaderControlMotionProbe']);
  const clickSample = { op: 'sampledClick', x: 100, y: 200, sampleDelaysMs: [0, 50, 10000] };
  assert.deepEqual(plan(clickSample).args, ['shell', 'uitest', 'uiInput', 'click', '100', '200']);
  assert.equal(plan(clickSample).kind, 'sampledClick');
  const held = { op: 'heldTouch', x: 100, y: 200, durationMs: 500 };
  assert.deepEqual(plan(held).args, ['shell', 'uinput', '-T', '-d', '100', '200', '-i', '500', '-u', '100', '200']);
  assert.equal(plan(held).kind, 'command');
  assert.equal(plan({ ...held, durationMs: 3000, sampleDelaysMs: [0, 1000, 3000] }).kind, 'sampledHeldTouch');
  for (const extra of [{ x: '100;reboot' }, { y: -1 }, { durationMs: 0 }, { durationMs: 3001 },
    { durationMs: 1.5 }, { durationMs: '500' }, { toX: 101 }, { action: 'CANCEL' }, { finger: 1 }, { args: ['shell', 'id'] }]) {
    assert.throws(() => plan({ ...held, ...extra }));
  }
  for (const op of [clickSample, { ...held, sampleDelaysMs: [0] }]) {
    assert.throws(() => operationPlan({ ...op, preflightConfirmed: false }, directory));
    for (const sampleDelaysMs of [[], [0, 0], [-1], [10001], [1.5], [0, 1, 2, 3, 4, 5]]) {
      assert.throws(() => plan({ ...op, sampleDelaysMs }));
    }
  }
  assert.throws(() => plan({ ...clickSample, velocity: 600 }));
  assert.throws(() => plan({ ...clickSample, key: 'Back' }));
  assert.throws(() => plan({ op: 'keyEvent', key: 'Power' }));
  for (const path of ['/data/local/tmp/reader-control-ok.png; reboot', '/data/local/tmp/reader-control-../x.png', '/data/local/tmp/other.png', '/data/local/tmp/reader-control-ok.png/../x']) {
    assert.throws(() => plan({ op: 'recv', path }));
  }
  assert.equal(plan({ op: 'recv', path: '/data/local/tmp/reader-control-ok.png' }).localPath, `${directory}/reader-control-ok.png`);
  assert.throws(() => plan({ op: 'screenCap', path: '/data/local/tmp/reader-control-ok.json' }));
  assert.deepEqual(plan({ op: 'start' }).args.slice(-3), ['--pb', 'readerControlMotionVerification', 'true']);
  assert.throws(() => plan({ op: 'start', bundle: 'other' }));
  assert.deepEqual(plan({ op: 'startNormal' }).args,
    ['shell', 'aa', 'start', '-a', 'EntryAbility', '-b', BUNDLE, '-m', 'entry']);
  assert.throws(() => plan({ op: 'startNormal', bundle: 'other' }));
  assert.throws(() => plan({ op: 'force-stop' }));
  assert.throws(() => plan({ op: 'force-stop', explicitPermit: 'true' }));
  assert.deepEqual(plan({ op: 'force-stop', explicitPermit: true }).args, ['shell', 'aa', 'force-stop', BUNDLE]);
  for (const op of ['install', 'uninstall', 'shell', 'reboot', 'clearData', 'kill', 'file send']) assert.throws(() => plan({ op }));
  const drag = { op: 'sampledDrag', fromX: 1, fromY: 2, toX: 3, toY: 4, sampleDelaysMs: [0, 20, 10000] };
  assert.equal(plan(drag).kind, 'sampledDrag');
  for (const sampleDelaysMs of [[], [0, 0], [-1], [10001], [1.5], [0, 1, 2, 3, 4, 5]]) assert.throws(() => plan({ ...drag, sampleDelaysMs }));
  assert.equal(operationPlan({ op: 'quit' }, directory).kind, 'quit');
  const down = { atMs: 0, action: 'DOWN', finger: 0, x: 100, y: 200 };
  const up = { ...down, atMs: 100, action: 'UP' };
  const prepare = { op: 'prepareTouchSequence', elfPath: '/private/tmp/reader-control-touch-sequence',
    elfSha256: TOUCH_ELF_SHA256, width: 1320, height: 2856, display: 0, plan: [down, up] };
  assert.equal(plan(prepare).planText, '0 DOWN 0 100 200\n100 UP 0 100 200\n');
  assert.equal(plan({ ...prepare, plan: [down, { ...down, finger: 1 }, { ...up, action: 'CANCEL' },
    { ...up, action: 'CANCEL', finger: 1 }] }).planText.split('\n').length, 5);
  for (const invalid of [{ elfSha256: '0'.repeat(64) }, { elfPath: '/tmp/other' }, { elfPath: 'reader-control-touch-sequence' },
    { display: 16 }, { width: 0 }, { plan: [] }, { plan: [down] }, { plan: [down, down, up] },
    { plan: [up, down] }, { plan: [down, { ...up, atMs: 10001 }] }, { plan: [down, { ...up, x: 1320 }] },
    { plan: [down, { ...up, x: '1;reboot' }] }, { plan: [down, { ...up, action: 'CANCEL' }, down, up] },
    { plan: [down, { ...up, shell: 'id' }] }, { plan: Array.from({ length: 258 }, (_, index) => index % 2 ? up : down) }]) {
    assert.throws(() => plan({ ...prepare, ...invalid }));
  }
  assert.throws(() => operationPlan({ ...prepare, preflightConfirmed: false }, directory));
  const ticket = '12345678-1234-4123-8123-123456789abc';
  assert.equal(plan({ op: 'dryRunTouchSequence', ticket }).kind, 'dryRunTouchSequence');
  const execute = { op: 'sampledTouchSequence', ticket, requestAuth: true, sampleDelaysMs: [0, 2000] };
  assert.equal(plan(execute).kind, 'sampledTouchSequence');
  for (const invalid of [{ requestAuth: undefined }, { requestAuth: 'true' }, { requestAuth: false },
    { ticket: `${ticket};reboot` }, { sampleDelaysMs: [1, 1] }, { sampleDelaysMs: [10001] }, { args: ['shell', 'id'] }]) {
    assert.throws(() => plan({ ...execute, ...invalid }));
  }
  assert.throws(() => plan({ op: 'dryRunTouchSequence', ticket, requestAuth: true }));
  assert.throws(() => operationPlan({ ...execute, preflightConfirmed: false }, directory));
  assert.equal(targetReference('test-serial'), createHash('sha256').update('test-serial').digest('hex').slice(0, 12));
  const owner = { pid: 123, targetRef: 'abc', probeNonce: 'owned' };
  assert.equal(ownerMatches(owner, owner), true);
  for (const changed of [{ pid: 124 }, { targetRef: 'other' }, { probeNonce: 'other' }]) assert.equal(ownerMatches({ ...owner, ...changed }, owner), false);
  assert.equal(commandOK({ status: 0, stdout: 'done', stderr: '' }), true);
  for (const output of ['Connect server failed', 'Device not found or connected', 'LIFECYCLE_TIMEOUT', 'Error: gesture failed',
    'Error loading shared library libark_jsruntime.so', 'Error relocating libace_napi.z.so: symbol not found']) {
    assert.equal(commandOK({ status: 0, stdout: output }), false, 'zero exit status cannot conceal stop-condition output');
  }
  process.stdout.write('reader control device probe pure argument/allowlist/ownership self-test: PASS (no HDC, no lock/device/filesystem writes)\n');
}

if (process.argv.length === 3 && process.argv[2] === '--self-test') selfTest();
else {
  try { await probe(optionsFrom(process.argv.slice(2))); }
  catch (error) { process.stderr.write(`reader-control device probe stopped: ${error.message}\n`); process.exitCode = 1; }
}
